"use client";

/**
 * Receipt. The device prints: a summary feeds out of a slot in the chassis a
 * line at a time, each with a small tick, and waits there to be torn off.
 * For an order confirmation, a payment, an invoice, a weekly recap, or the
 * summary of what an automated run did.
 *
 * It prints when it arrives, after the page has loaded (a confirmation that
 * appears when payment goes through); one that's on the page from the start
 * is simply there. Change `printKey` to print it again.
 *
 * Everything on it is text in the page from the start (a heading, a list of
 * lines, a total), so a screen reader never waits for the paper; the feed is
 * only drawing. Tearing it off has a button.
 */
import { useId, useLayoutEffect, useRef, useState, useSyncExternalStore, type ReactNode } from "react";
import { useReducedMotionRef } from "echo-ui-core/tactile";
import { useSoundOptional, type SoundRecipe } from "echo-ui-core/sound";
import { HardwareButton } from "../hardware-button";
import { barcode } from "./barcode";
import "./receipt.css";

export interface ReceiptLine {
  label: ReactNode;
  value: ReactNode;
}

export interface ReceiptProps {
  /** Printed at the top, and the receipt's heading. */
  title: string;
  /** A line under the title: a number, a date, a place. */
  meta?: string;
  /** What it lists, each with its value across a dotted leader. */
  lines: readonly ReceiptLine[];
  /** The bottom line, printed bold under a rule. */
  total?: ReceiptLine;
  /** Printed at the very bottom: how it was paid, a thank-you, what to do next. */
  footer?: string;
  /** A reference printed as a barcode, with the code in text beneath it. */
  code?: string;
  /** Shows a Tear off key; called once the paper has dropped away. */
  onTear?: () => void;
  /** Print it again whenever this changes. */
  printKey?: string | number;
  /** The heading's level. Default 3. */
  headingLevel?: 2 | 3 | 4;
}

/** A thermal printer's step: quieter and shorter than a key. */
const FEED: SoundRecipe = { wave: "square", freq: 2600, decay: 0.01, gain: 0.03 };
const STEP_MS = 90;

const never = () => () => {};

export function Receipt({ title, meta, lines, total, footer, code, onTear, printKey, headingLevel = 3 }: ReceiptProps) {
  const Heading = `h${headingLevel}` as const;
  const id = useId();
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const feed = useRef<HTMLDivElement>(null);
  const paper = useRef<HTMLDivElement>(null);
  const [torn, setTorn] = useState(false);
  const printing = useRef(false);
  // False while the page hydrates (it was already there), true for a receipt
  // that mounts afterwards: the one that has just arrived and should print.
  const onClient = useSyncExternalStore(never, () => true, () => false);
  const arrivedLate = useRef(onClient);
  const lastKey = useRef(printKey);
  /** The pending step of the print under way: one print at a time, and none after unmounting. */
  const step = useRef<number | undefined>(undefined);

  /** Ends the print under way where it stands: the paper rests whole in the window. */
  const settle = () => {
    window.clearTimeout(step.current);
    feed.current?.removeAttribute("data-printing");
    feed.current?.style.removeProperty("--receipt-shown");
    printing.current = false;
  };

  const print = () => {
    const window_ = feed.current;
    const sheet = paper.current;
    // Printing again mid-print starts over, rather than feeding twice at once.
    window.clearTimeout(step.current);
    if (!window_ || !sheet || reduced.current) {
      settle();
      return;
    }
    const full = sheet.offsetHeight;
    // The paper leaves the slot bottom edge first, a line per step.
    const rows = [...sheet.querySelectorAll<HTMLElement>("[data-line]")].reverse();
    const stops = [...rows.map((row) => full - row.offsetTop), full];
    printing.current = true;
    window_.setAttribute("data-printing", "");
    window_.style.setProperty("--receipt-shown", "0px");
    let i = 0;
    const next = () => {
      const stop = stops[i++];
      if (stop === undefined) {
        settle();
        return;
      }
      window_.style.setProperty("--receipt-shown", `${stop}px`);
      sound?.play(FEED);
      step.current = window.setTimeout(next, STEP_MS);
    };
    step.current = window.setTimeout(next, STEP_MS);
  };

  // Arriving after the page has settled, it prints; so does a new printKey.
  // Whatever stops this effect (unmounting, a new printKey, or its effects
  // running again, as StrictMode and <Activity> do) settles the paper whole:
  // a print cut off mid-feed would otherwise leave it in the slot (BUG-118).
  useLayoutEffect(() => {
    const again = printKey !== lastKey.current;
    lastKey.current = printKey;
    if (!arrivedLate.current && !again) return;
    arrivedLate.current = false;
    setTorn(false);
    print();
    return settle;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [printKey]);

  const tear = () => {
    if (printing.current) return;
    sound?.play("release");
    setTorn(true);
    window.setTimeout(() => onTear?.(), reduced.current ? 0 : 420);
  };

  return (
    <section className="echo-receipt" aria-labelledby={`${id}-title`} data-torn={torn || undefined}>
      <div className="echo-receipt__slot" aria-hidden="true" />
      <div ref={feed} className="echo-receipt__feed">
        <div ref={paper} className="echo-receipt__paper">
          <Heading id={`${id}-title`} className="echo-receipt__title" data-line="">
            {title}
          </Heading>
          {meta ? (
            <p className="echo-receipt__meta" data-line="">
              {meta}
            </p>
          ) : null}
          <dl className="echo-receipt__lines">
            {lines.map((line, i) => (
              <div key={i} className="echo-receipt__line" data-line="">
                <dt>{line.label}</dt>
                <span className="echo-receipt__leader" aria-hidden="true" />
                <dd>{line.value}</dd>
              </div>
            ))}
            {total ? (
              <div className="echo-receipt__line" data-total="" data-line="">
                <dt>{total.label}</dt>
                <span className="echo-receipt__leader" aria-hidden="true" />
                <dd>{total.value}</dd>
              </div>
            ) : null}
          </dl>
          {code ? (
            <div className="echo-receipt__code" data-line="">
              <svg viewBox="0 0 200 36" preserveAspectRatio="none" aria-hidden="true" focusable="false">
                {barcode(code).map((bar, i) => (
                  <rect key={i} x={bar.x} y={0} width={bar.w} height={36} />
                ))}
              </svg>
              <span>{code}</span>
            </div>
          ) : null}
          {footer ? (
            <p className="echo-receipt__footer" data-line="">
              {footer}
            </p>
          ) : null}
        </div>
      </div>
      {onTear ? (
        <div className="echo-receipt__tear">
          <HardwareButton size="sm" disabled={torn} onClick={tear}>
            Tear off
          </HardwareButton>
        </div>
      ) : null}
    </section>
  );
}

/**
 * Receipt. A slot recessed into the chassis, and paper hanging from it: dark
 * ink (the chassis colour) on the paper colour, torn at both ends. While it
 * prints, the paper leaves the slot a line at a time. Composes var(--echo-*)
 * — no hex literals; the only fixed values are the single-key-light model.
 */
.echo-receipt {
  display: grid;
  justify-items: center;
  /* Slot, paper, key: stacked at the top, however tall the space it's in. */
  align-content: start;
  align-self: start;
  inline-size: min(100%, 320px);
  max-inline-size: 100%;
  min-inline-size: 0;
}

/* The slot: a narrow recess the paper comes out of. */
.echo-receipt__slot {
  position: relative;
  z-index: var(--echo-z-raised, 1);
  box-sizing: border-box;
  inline-size: 100%;
  block-size: 14px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-well);
  box-shadow:
    inset 0 3px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.95 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.06 * var(--echo-gloss, 1))),
    0 1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

.echo-receipt__feed {
  position: relative;
  inline-size: calc(100% - 2 * var(--echo-space-8));
  margin-block-start: -7px;
}
/* Printing: only what has left the slot shows, bottom edge first. */
.echo-receipt__feed[data-printing] {
  block-size: var(--receipt-shown, 0px);
  overflow: hidden;
}
.echo-receipt__feed[data-printing] .echo-receipt__paper {
  position: absolute;
  inset-inline: 0;
  inset-block-end: 0;
}

.echo-receipt__paper {
  box-sizing: border-box;
  display: grid;
  gap: var(--echo-space-2);
  padding: var(--echo-space-10) var(--echo-space-8) var(--echo-space-10);
  color: var(--echo-paper-ink, var(--echo-surface));
  /* The shadow the slot throws on the paper, then the paper itself. */
  background:
    linear-gradient(180deg, color-mix(in oklab, var(--echo-cast-ink, black) calc(0.22 * var(--echo-shade, 1) * 100%), transparent), transparent var(--echo-space-10)),
    var(--echo-paper-stock, var(--echo-text));
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-xs);
  line-height: var(--echo-leading-snug, 1.4);
  font-variant-numeric: tabular-nums;
  /* Torn at both ends: a row of small teeth (a mask: only its shape counts). */
  -webkit-mask:
    conic-gradient(from 135deg at top, transparent, var(--echo-seam) 1deg 89deg, transparent 90deg) top / 12px 51% repeat-x,
    conic-gradient(from -45deg at bottom, transparent, var(--echo-seam) 1deg 89deg, transparent 90deg) bottom / 12px 51% repeat-x;
  mask:
    conic-gradient(from 135deg at top, transparent, var(--echo-seam) 1deg 89deg, transparent 90deg) top / 12px 51% repeat-x,
    conic-gradient(from -45deg at bottom, transparent, var(--echo-seam) 1deg 89deg, transparent 90deg) bottom / 12px 51% repeat-x;
  transition:
    translate var(--echo-duration-flood) var(--echo-ease-glide),
    rotate var(--echo-duration-flood) var(--echo-ease-glide),
    opacity var(--echo-duration-pop) ease;
}

.echo-receipt__title {
  margin: 0;
  text-align: center;
  font-family: inherit;
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
}
.echo-receipt__meta,
.echo-receipt__footer {
  margin: 0;
  text-align: center;
  font-size: var(--echo-text-2xs);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  text-transform: uppercase;
}
.echo-receipt__meta {
  padding-block-end: var(--echo-space-4);
  border-block-end: var(--echo-border-fine, 1.5px) dashed color-mix(in oklab, var(--echo-surface) 45%, transparent);
}

.echo-receipt__lines {
  display: grid;
  gap: var(--echo-space-1);
  margin: var(--echo-space-3) 0 0;
}
.echo-receipt__line {
  display: flex;
  align-items: baseline;
  gap: var(--echo-space-3);
  min-inline-size: 0;
}
.echo-receipt__line dt,
.echo-receipt__line dd {
  margin: 0;
  min-inline-size: 0;
  overflow-wrap: anywhere;
}
.echo-receipt__line dd {
  flex: none;
  text-align: end;
}
.echo-receipt__leader {
  flex: 1 1 var(--echo-space-6);
  min-inline-size: var(--echo-space-6);
  border-block-end: var(--echo-border-fine, 1.5px) dotted color-mix(in oklab, var(--echo-surface) 50%, transparent);
  translate: 0 -0.3em;
}
.echo-receipt__line[data-total] {
  margin-block-start: var(--echo-space-4);
  padding-block-start: var(--echo-space-4);
  border-block-start: var(--echo-border-fine, 1.5px) dashed color-mix(in oklab, var(--echo-surface) 45%, transparent);
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-bold, 700);
}

.echo-receipt__code {
  display: grid;
  justify-items: center;
  gap: var(--echo-space-1);
  margin-block: var(--echo-space-5) var(--echo-space-2);
  font-size: var(--echo-text-2xs);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
}
.echo-receipt__code svg {
  display: block;
  inline-size: 100%;
  block-size: 36px;
  fill: var(--echo-surface);
}

.echo-receipt__tear {
  margin-block-start: var(--echo-space-6);
}

/* Torn off: the paper drops away. */
.echo-receipt[data-torn] .echo-receipt__paper {
  translate: 0 48px;
  rotate: -4deg;
  opacity: 0;
}

@media (prefers-reduced-motion: reduce) {
  .echo-receipt__paper {
    transition: opacity var(--echo-duration-swap) linear;
  }
  .echo-receipt[data-torn] .echo-receipt__paper {
    translate: none;
    rotate: none;
  }
}
@media (forced-colors: active) {
  .echo-receipt__paper {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
    -webkit-mask: none;
    mask: none;
  }
  .echo-receipt__code svg {
    fill: CanvasText;
  }
}

/**
 * A barcode drawn from a reference: the same code always prints the same
 * bars. It's a picture of a barcode, not a scannable one; the code itself is
 * printed in text beneath it.
 */
export interface Bar {
  x: number;
  w: number;
}

/** Bars across a 200-unit strip, with quiet zones at both ends. */
export function barcode(code: string, width = 200): Bar[] {
  let seed = 2166136261;
  for (const ch of code) {
    seed ^= ch.charCodeAt(0);
    seed = Math.imul(seed, 16777619) >>> 0;
  }
  const next = () => {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    seed >>>= 0;
    return seed;
  };
  const bars: Bar[] = [];
  let x = 8;
  while (x < width - 10) {
    const w = 1 + (next() % 3);
    const gap = 1 + (next() % 3);
    if (x + w > width - 8) break;
    bars.push({ x, w });
    x += w + gap;
  }
  return bars;
}
